 * Author: @arjun-kumar (https://tailwindflex.com/@arjun-kumar)
 * Source: https://tailwindflex.com/@arjun-kumar/buuton
 * Attribution: Créé par @arjun-kumar sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function Buuton() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes">
  <title>Account Security Center</title>
  <link href="https://fonts.googleapis.com/css2?family=Inter:opsz,wght@14..32,400;14..32,500;14..32,600;14..32,700&display=swap" rel="stylesheet">
  <style>
    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    body {
      background: radial-gradient(circle at 10% 30%, #f8fafc, #eef2ff);
      font-family: 'Inter', system-ui, -apple-system, sans-serif;
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 1.5rem;
    }

    .glass-panel {
      max-width: 560px;
      width: 100%;
      background: rgba(255, 255, 255, 0.96);
      backdrop-filter: blur(2px);
      border-radius: 2.5rem;
      box-shadow: 0 25px 45px -12px rgba(0, 0, 0, 0.3), 0 1px 2px rgba(0,0,0,0.05);
      padding: 2rem 2rem 2.2rem;
      transition: all 0.2s;
      border: 1px solid rgba(255,255,255,0.7);
    }

    .user-row {
      display: flex;
      align-items: center;
      gap: 1.2rem;
      margin-bottom: 2rem;
      border-bottom: 2px solid #e9edf2;
      padding-bottom: 1.5rem;
    }

    .avatar-badge {
      background: linear-gradient(125deg, #1e293b, #0f172a);
      width: 58px;
      height: 58px;
      border-radius: 32px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.9rem;
      font-weight: 600;
      color: white;
      box-shadow: 0 10px 15px -8px rgba(0,0,0,0.2);
    }

    .user-text h3 {
      font-size: 1.6rem;
      font-weight: 700;
      color: #0a0c10;
      letter-spacing: -0.3px;
    }

    .user-text p {
      font-size: 0.85rem;
      color: #475569;
      margin-top: 4px;
    }

    .btn-group {
      display: flex;
      flex-direction: row;
      flex-wrap: wrap;
      align-items: center;
      justify-content: flex-start;
      gap: 1.2rem;
      margin: 1.5rem 0 1rem;
    }

    .btn-logout {
      background: #dc2626;
      border: none;
      border-radius: 3rem;
      padding: 0.75rem 2rem;
      font-weight: 700;
      font-size: 0.95rem;
      font-family: inherit;
      color: white;
      cursor: pointer;
      transition: all 0.2s ease;
      box-shadow: 0 6px 14px rgba(220, 38, 38, 0.25);
      display: inline-flex;
      align-items: center;
      gap: 10px;
    }

    .btn-logout:hover {
      background: #b91c1c;
      transform: translateY(-2px);
      box-shadow: 0 12px 20px -8px rgba(185, 28, 28, 0.4);
    }

    .btn-logout:active {
      transform: translateY(1px);
    }

    .btn-delete {
      background: transparent;
      border: 1.8px solid #dc2626;
      border-radius: 3rem;
      padding: 0.7rem 1.8rem;
      font-weight: 700;
      font-size: 0.95rem;
      font-family: inherit;
      color: #dc2626;
      cursor: pointer;
      transition: all 0.2s ease;
      background-color: rgba(220, 38, 38, 0.02);
      display: inline-flex;
      align-items: center;
      gap: 10px;
    }

    .btn-delete:hover {
      background: #fff0f0;
      border-color: #b91c1c;
      color: #b91c1c;
      transform: translateY(-1px);
      box-shadow: 0 8px 18px -10px rgba(220,38,38,0.3);
    }

    .btn-delete:active {
      transform: translateY(1px);
    }

    .footnote {
      margin-top: 2rem;
      font-size: 0.7rem;
      color: #5b6e8c;
      background: #f1f5f9;
      padding: 0.7rem 1rem;
      border-radius: 2rem;
      text-align: center;
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
    }

    /* modern dialog overlay */
    .dialog-overlay {
      position: fixed;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      background: rgba(0, 0, 0, 0.55);
      backdrop-filter: blur(8px);
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 1000;
      opacity: 0;
      visibility: hidden;
      transition: all 0.2s ease;
    }

    .dialog-overlay.active {
      opacity: 1;
      visibility: visible;
    }

    .dialog-box {
      background: #ffffff;
      max-width: 420px;
      width: 90%;
      border-radius: 2rem;
      box-shadow: 0 30px 55px rgba(0, 0, 0, 0.35);
      padding: 2rem 1.8rem 2rem;
      text-align: center;
      transform: scale(0.96);
      transition: transform 0.2s cubic-bezier(0.2, 0.9, 0.4, 1.1);
    }

    .dialog-overlay.active .dialog-box {
      transform: scale(1);
    }

    .dialog-icon {
      font-size: 3.2rem;
      margin-bottom: 0.75rem;
    }

    .dialog-head {
      font-size: 1.7rem;
      font-weight: 800;
      color: #0f172a;
      margin: 0.3rem 0 0.5rem;
    }

    .dialog-text {
      font-size: 0.95rem;
      color: #334155;
      line-height: 1.5;
      margin-bottom: 2rem;
      padding: 0 0.2rem;
    }

    .dialog-buttons {
      display: flex;
      flex-wrap: wrap;
      gap: 14px;
      justify-content: center;
    }

    .dialog-btn {
      border: none;
      padding: 0.7rem 1.8rem;
      border-radius: 3rem;
      font-weight: 600;
      font-family: inherit;
      font-size: 0.9rem;
      cursor: pointer;
      transition: 0.15s;
      min-width: 120px;
    }

    .btn-yes {
      background: #dc2626;
      color: white;
      box-shadow: 0 2px 8px rgba(220,38,38,0.3);
    }

    .btn-yes:hover {
      background: #b91c1c;
      transform: translateY(-1px);
    }

    .btn-no {
      background: #e9eef3;
      color: #1e293b;
    }

    .btn-no:hover {
      background: #dce3ec;
      transform: translateY(-1px);
    }

    .toast-message {
      position: fixed;
      bottom: 28px;
      left: 50%;
      transform: translateX(-50%) translateY(20px);
      background: #0f172ad9;
      backdrop-filter: blur(12px);
      color: white;
      padding: 0.8rem 1.8rem;
      border-radius: 60px;
      font-size: 0.9rem;
      font-weight: 500;
      display: flex;
      align-items: center;
      gap: 12px;
      z-index: 1100;
      opacity: 0;
      transition: opacity 0.2s, transform 0.2s;
      pointer-events: none;
      box-shadow: 0 8px 20px rgba(0,0,0,0.2);
    }

    .toast-message.show {
      opacity: 1;
      transform: translateX(-50%) translateY(0);
    }

    button:disabled {
      opacity: 0.55;
      cursor: not-allowed;
      transform: none !important;
    }
  </style>
</head>
<body>

<div class="glass-panel">
  <div class="user-row">
    <div class="avatar-badge"></div>
    <div class="user-text">
      <h3>Olivia Chen</h3>
      <p>olivia.c@creativestudio.com • premium</p>
    </div>
  </div>

  <div class="btn-group">
    <button class="btn-logout" id="logoutActionBtn">
      <span></span> Logout
    </button>
    <button class="btn-delete" id="deleteActionBtn">
      <span></span> Delete Account
    </button>
  </div>
  <div class="footnote">
     Critical actions require confirmation · Deleted data cannot be restored.
  </div>
</div>

<div id="deleteConfirmModal" class="dialog-overlay">
  <div class="dialog-box">
    <div class="dialog-icon"></div>
    <div class="dialog-head">Delete account forever?</div>
    <div class="dialog-text">
      This will erase your profile, history, and all personal data.<br>
      <strong>No recovery possible.</strong><br><br>
      Are you absolutely sure?
    </div>
    <div class="dialog-buttons">
      <button class="dialog-btn btn-yes" id="yesDeleteBtn">Yes, delete</button>
      <button class="dialog-btn btn-no" id="noDeleteBtn">No, keep it</button>
    </div>
  </div>
</div>

<div id="logoutConfirmModal" class="dialog-overlay">
  <div class="dialog-box">
    <div class="dialog-icon"></div>
    <div class="dialog-head">Sign out?</div>
    <div class="dialog-text">
      You will be logged out of your account.<br>
      You can always log back in.
    </div>
    <div class="dialog-buttons">
      <button class="dialog-btn btn-yes" id="yesLogoutBtn">Logout</button>
      <button class="dialog-btn btn-no" id="noLogoutBtn">Cancel</button>
    </div>
  </div>
</div>

<div id="globalToast" class="toast-message">
  <span></span> <span id="toastLabel">Action completed</span>
</div>


</body>
</html>" }} />
  );
}
